mapper.sql:
SELECT a.id,a.reconciliation_id, a.logistics_bill_id, ca.logistics_bill_detail_id, ca.estimated_bill_id, ca.weight_allocation_id, a.report_period_id, a.account_period, a.status, a.supplier_id, a.supplier_name, a.business_code, a.business_type, a.transport_no, a.reconciliation_month as reconciliationMonth, to_char(a.reconciliation_month, 'YYYY-MM') AS reconciliationMonthStr, a.shop_id, a.shop_name, a.from_warehouse_id, a.from_warehouse_name, a.to_warehouse_id, a.to_warehouse_name, a.source_id,a.source_code,a.org_id as orgId,a.org_name as orgName,ca.init_first_mile_detail_id,ca.source_detail_id,ca.reconciliation_detail_id, ca.id as costId,ca.sku_id, ca.sku_no, ca.platform_sku_no, ca.delivery_qty, ca.allocated_weight, ca.product_cost, ca.product_total_cost,ca.init_receive_qty, ca.last_month_receive_qty, ca.current_month_receive_qty, ca.as_last_month_receive_qty,ca.as_current_month_receive_qty, ca.weight_unit, ca.currency, ca.bill_source_type,lbd.sign_time as receiveTime, cad.id as detailId,cad.fee_type, cad.allocation_type, cad.amount as amount, cad.allocated_amount as allocatedAmount, cad.product_allocated_amount as productAllocatedAmount, cad.init_transit_cost as initTransitCost,cad.init_estimated_cost as initEstimatedCost, cad.mid_period_transit_cost as midPeriodTransitCost, cad.current_period_allocated_cost as currentPeriodAllocatedCost, cad.end_period_transit_cost as endPeriodTransitCost, cad.end_period_estimated_cost as endPeriodEstimatedCost, a.create_time as createTime,a.create_user_name as createUserName, a.update_user_name as updateUserName,a.update_time as updateTime, rpm.month as reportPeriodMonth,to_char(rpm.month, 'YYYY-MM') AS reportPeriodStr FROM first_mile_cost_allocation a LEFT JOIN first_mile_sku_cost_allocation ca ON ca.main_id = a.id AND ca.is_deleted = FALSE LEFT JOIN first_mile_sku_cost_allocation_detail cad ON cad.cost_main_id = ca.id AND cad.is_deleted = FALSE LEFT JOIN logistics_bill_detail lbd ON lbd.id = ca.logistics_bill_detail_id AND lbd.is_deleted = FALSE LEFT JOIN report_period_month rpm ON rpm.id = a.report_period_id AND rpm.is_deleted = FALSE
${params.sqlMap.default} and a.is_deleted=false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
a.create_time DESC,a.id,ca.id,cad.fee_type

mapper.select:
SELECT COUNT(distinct a.id) AS count, a.status AS tabFlag FROM first_mile_cost_allocation a WHERE a.is_deleted=false
${permissionSql}
GROUP BY a.status

