SELECT a.id,a.reconciliation_id, a.logistics_bill_id, ca.logistics_bill_detail_id, ca.estimated_bill_id, ca.weight_allocation_id, a.report_period_id, a.account_period, a.status, a.supplier_id, a.supplier_name, a.business_code, a.business_type, a.transport_no, a.reconciliation_month as reconciliationMonth, to_char(a.reconciliation_month, 'YYYY-MM') AS reconciliationMonthStr, a.shop_id, a.shop_name, a.from_warehouse_id, a.from_warehouse_name, a.to_warehouse_id, a.to_warehouse_name, a.source_id,a.source_code,a.org_id,a.org_name,ca.init_first_mile_detail_id,ca.source_detail_id,ca.reconciliation_detail_id, ca.id as costId,ca.sku_id, ca.sku_no, ca.platform_sku_no, ca.delivery_qty, ca.allocated_weight,ca.currency_symbol, ca.product_cost, ca.product_total_cost,ca.init_receive_qty, ca.last_month_receive_qty, ca.current_month_receive_qty, ca.as_last_month_receive_qty,ca.as_current_month_receive_qty, ca.weight_unit, ca.currency, ca.bill_source_type,lbd.sign_time as receiveTime, rpm.month as reportPeriodMonth,to_char(rpm.month, 'YYYY-MM') AS reportPeriodStr FROM first_mile_cost_allocation a LEFT JOIN first_mile_sku_cost_allocation ca ON ca.main_id = a.id AND ca.is_deleted = FALSE LEFT JOIN logistics_bill_detail lbd ON lbd.id = ca.logistics_bill_detail_id AND lbd.is_deleted = FALSE LEFT JOIN report_period_month rpm ON rpm.id = a.report_period_id AND rpm.is_deleted = FALSE where a.is_deleted=false
